		public virtual void GetUiDisplay_GetPlayerName(global::Dpr.Battle.Logic.BattleViewBase.UiDisplayPlayerNameInfo pInfo, in byte clientID) {
            if (pInfo == null)
                return;

            pInfo.Reset();
            if (m_pMainModule == null)
                return;

            if (!m_pMainModule.IsClientNPC(clientID))
                pInfo.pMyStatus = m_pMainModule.GetClientPlayerData(clientID);

            if (pInfo.pMyStatus != null)
            {
                if (pInfo.ipName != null)
                    pInfo.ipName = pInfo.pMyStatus.name;

                pInfo.gender = pInfo.pMyStatus.GetSex();
                pInfo.pokeLanguageID = pInfo.pMyStatus.lang;
            }
            else
            {
                string trainerName = GetTrainerName(clientID);
                if (trainerName == null)
                    return;

                if (pInfo.ipName == null)
                    return;

                byte myClientID = GetClientID();
                MyStatus myStatus = m_pMainModule.GetClientPlayerData(myClientID);
                pInfo.ipName = trainerName;
                pInfo.gender = GetTrainerSex(myClientID);
                pInfo.pokeLanguageID = myStatus.lang;
            }
        }
		public virtual bool IsWazaAffinityDisplayEnable(byte defPokeID) {
            BtlCompetitor competitor = m_pMainModule.GetCompetitor(true);
            if (competitor == BtlCompetitor.BTL_COMPETITOR_INST || competitor == BtlCompetitor.BTL_COMPETITOR_COMM)
                return true;

            MonsNo monsno = (MonsNo)GetBattleContainer().GetPokeParamConst(defPokeID).GetMonsNo();
            if (!poketool.ExtendData.IsExistLocalZukanStatic((uint)monsno))
                return true;

            return m_pMainModule.IsZukanPokeSeeOnBattleStart(monsno);
        }
		public virtual global::Pml.Battle.TypeAffinity.AboutAffinityID CalcWazaAffinityAbout(byte atkPokeID, byte defPokeID, global::Pml.WazaNo waza, out bool isDisplayEnable) {
            if (!IsWazaAffinityDisplayEnable(defPokeID) || WAZADATA.GetDamageType(waza) == WazaDamageType.NONE || tables.IsNotDisplayUiAffinity(waza))
            {
                isDisplayEnable = false;
                return TypeAffinity.AboutAffinityID.NORMAL;
            }

            isDisplayEnable = true;
            TypeAffinity.AffinityID affinity = m_battleSimulator.CalcTypeAffinity(atkPokeID, defPokeID, waza, true);
            return calc.TypeAffAbout(affinity);
        }
